import areaJson from "@/public/data/area.json";
import companionshipsJson from "@/public/data/companionships.json";
import walksJson from "@/public/data/walks.json";
import actionsJson from "@/public/data/actions.json";
import appointmentsJson from "@/public/data/appointments.json";
import zonesJson from "@/public/data/zones.json";
import streetsJson from "@/public/data/streets.json";
import type { Action, Appointment, Area, Companionship, Street, Walk, Zone } from "./types";

// Generated by scripts/generate.ts and bundled at build time. No fetch.
export const area = areaJson as Area;
export const companionships = companionshipsJson as Companionship[];
export const walks = walksJson as unknown as Walk[];
export const actions = actionsJson as unknown as Action[];
export const appointments = appointmentsJson as unknown as Appointment[];
export const zones = zonesJson as unknown as Zone[];
/** Every walkable street in the area, for drawing the unwalked ones. */
export const streets = streetsJson as unknown as Street[];

export function bbox(points: [number, number][]): [number, number, number, number] {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const [x, y] of points) {
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  return [minX, minY, maxX, maxY];
}
